#include <bits/stdc++.h>
using namespace std;

vector<int> get_primes(int limit) {
    vector<bool> is_prime(limit + 1, true);
    vector<int> primes;
    if (limit >= 2) {
        is_prime[0] = is_prime[1] = false;
        for (int i = 2; i <= limit; ++i) {
            if (is_prime[i]) {
                primes.push_back(i);
                if (i * 1LL * i <= limit) {
                    for (int j = i * i; j <= limit; j += i) {
                        is_prime[j] = false;
                    }
                }
            }
        }
    }
    return primes;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, a, b;
    cin >> m >> a >> b;

