    int best_w = 0, best_h = 0, best_area = 0;

    for (int h : primes) {
        for (int w : primes) {
            if (w > h) continue; // w/h <= 1
            if (w * 1LL * h > m) continue;
            // w/h >= a/b  =>  w * b >= a * h
            if (w * 1LL * b < a * 1LL * h) continue;

            int area = w * h;
            if (area > best_area) {
                best_area = area;
                best_w = w;
                best_h = h;
            }
        }
    }

    cout << best_w << " " << best_h << "\n";
    return 0;
}

