using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 m, a, b;
    cin >> m >> a >> b;

    // Generate all primes up to m using sieve.
    vector<bool> isPrime(m + 1, true);
    if (m >= 0) isPrime[0] = false;
    if (m >= 1) isPrime[1] = false;
    for (int64 i = 2; i * i <= m; ++i) {
        if (isPrime[i]) {
            for (int64 j = i * i; j <= m; j += i) {
                isPrime[j] = false;
            }
        }
    }

    vector<int> primes;
    for (int i = 2; i <= m; ++i) {
        if (isPrime[i]) primes.push_back(i);
    }

    int64 bestArea = 0;
    int bestW = 0, bestH = 0;

    int n = (int)primes.size();

    // Let width = p, height = q, with p <= q.
    // Need: p*q <= m and a/b <= p/q <= 1
    // i.e. p <= q and b*p >= a*q
    for (int i = 0; i < n; ++i) {
        int64 p = primes[i];

        // q must satisfy q <= m / p
        int64 maxQ = m / p;
        if (maxQ < p) break; // since q >= p

        // Find largest prime q <= maxQ
        int hi = upper_bound(primes.begin() + i, primes.end(), (int)maxQ) - primes.begin() - 1;

        // Try decreasing q while ratio condition fails.
        for (int j = hi; j >= i; --j) {
            int64 q = primes[j];
            int64 area = p * q;
            if (area <= bestArea) break; // smaller q only decreases area

            if (b * p >= a * q) {
                bestArea = area;
                bestW = (int)p;
                bestH = (int)q;
                break; // for this p, this is the best q
            }
        }
    }

    cout << bestW << " " << bestH << "\n";
    return 0;
}

