        int M = (int) m;
        boolean[] isComposite = new boolean[M + 1];
        isComposite[0] = isComposite[1] = true;
        for (int i = 2; (long)i * i <= M; i++) {
            if (!isComposite[i]) {
                for (int j = i * i; j <= M; j += i) {
                    isComposite[j] = true;
                }
            }
        }

        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= M; i++) {
            if (!isComposite[i]) primes.add(i);
        }

        long bestArea = -1;
        int bestW = -1, bestH = -1;

        for (int wi = 0; wi < primes.size(); wi++) {
            long w = primes.get(wi);
            if (w * w > m) break; // since h >= w, w*h >= w*w > m

            // h in [w, m/w], and w*b >= h*a => h <= w*b/a
            long maxH = Math.min(m / w, w * b / a);

            // Find largest prime h in [w, maxH]
            // Binary search for maxH in primes list
            int lo = wi, hi = primes.size() - 1;
            // find largest index where primes[idx] <= maxH
            int idx = -1;
            int left = wi, right = primes.size() - 1;
            while (left <= right) {
                int mid = (left + right) / 2;
                if (primes.get(mid) <= maxH) {
                    idx = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            if (idx >= wi) {
                long h = primes.get(idx);
                long area = w * h;
                if (area > bestArea) {
                    bestArea = area;
                    bestW = (int) w;
                    bestH = (int) h;
                }
            }
        }

        System.out.println(bestW + " " + bestH);
    }
