import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        long m = fs.nextLong();
        long a = fs.nextLong();
        long b = fs.nextLong();

        int limit = (int) Math.min(m, Integer.MAX_VALUE - 5L);
        boolean[] isPrime = sieve(limit);

        int bestW = 0, bestH = 0;
        long bestArea = 0;

        // width <= height because width/height <= 1
        for (int h = 2; h <= limit; h++) {
            if (!isPrime[h]) continue;

            long maxWByArea = m / h;
            if (maxWByArea < 2) continue;

            long maxWByRatio = h; // width/height <= 1
            long maxW = Math.min(maxWByArea, maxWByRatio);
            if (maxW < 2) continue;

            // Need width/height >= a/b => width >= ceil(a*h / b)
            long minW = (a * (long) h + b - 1) / b;
            if (minW > maxW) continue;
            if (minW < 2) minW = 2;

            int w = largestPrimeLE((int) maxW, isPrime);
            if (w < minW) continue;

            long area = (long) w * h;
            if (area > bestArea) {
                bestArea = area;
                bestW = w;
                bestH = h;
            }
        }

        if (bestArea == 0) {
            System.out.println("0 0");
        } else {
            System.out.println(bestW + " " + bestH);
        }
    }

    static boolean[] sieve(int n) {
        boolean[] isPrime = new boolean[n + 1];
        if (n >= 2) Arrays.fill(isPrime, true);
        if (n >= 0) isPrime[0] = false;
        if (n >= 1) isPrime[1] = false;

        for (int i = 2; (long) i * i <= n; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= n; j += i) {
                    isPrime[j] = false;
                }
            }
        }
        return isPrime;
    }

    static int largestPrimeLE(int x, boolean[] isPrime) {
        for (int i = x; i >= 2; i--) {
            if (isPrime[i]) return i;
        }
        return -1;
    }
}

