    scanf("%d %d/%d", &m, &a, &b);

    // Sieve primes up to m
    int *is_prime = malloc((m + 1) * sizeof(int));
    for (int i = 2; i <= m; i++) is_prime[i] = 1;
    is_prime[0] = is_prime[1] = 0;
    for (int i = 2; i * i <= m; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= m; j += i)
                is_prime[j] = 0;
        }
    }

    int best_w = 0, best_h = 0, best_area = 0;

    for (int h = 2; h <= m; h++) {
        if (!is_prime[h]) continue;
        // width >= ceil(h * a / b)
        long long min_w_num = (long long)h * a;
        int min_w = (min_w_num + b - 1) / b; // integer ceil
        int max_w = h; // width <= height
        if (min_w > max_w) continue;

        // Find largest prime w in [min_w, max_w] such that w*h <= m
        for (int w = max_w; w >= min_w; w--) {
            if (!is_prime[w]) continue;
            if ((long long)w * h > m) continue;
            int area = w * h;
            if (area > best_area) {
                best_area = area;
                best_w = w;
                best_h = h;
            }
            break; // largest w found for this h
        }
    }

    printf("%d %d\n", best_w, best_h);

    free(is_prime);
    return 0;
}

