        if (is_composite[w]) continue;
        if ((long long)w * w > m) break; // w <= h, so w*w <= w*h <= m
        // Actually w can equal h too
        for (int h = w; (long long)w * h <= m; h++) {
            if (is_composite[h]) continue;
            // Check ratio: w*b >= a*h
            if ((long long)w * b >= (long long)a * h) {
