typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    ll m, a, b;
    while (scanf("%lld %lld %lld", &m, &a, &b) == 3) {
        if (m == 0 && a == 0 && b == 0) break;

        int limit = (int)sqrt((double)m) + 5;
        char *is_prime = (char *)malloc((limit + 1) * sizeof(char));
        for (int i = 0; i <= limit; ++i) is_prime[i] = 1;
        if (limit >= 0) is_prime[0] = 0;
        if (limit >= 1) is_prime[1] = 0;

        for (int i = 2; (ll)i * i <= limit; ++i) {
            if (is_prime[i]) {
                for (int j = i * i; j <= limit; j += i) is_prime[j] = 0;
            }
        }

        ll *primes = (ll *)malloc((limit + 1) * sizeof(ll));
        int pcnt = 0;
        for (int i = 2; i <= limit; ++i) {
            if (is_prime[i]) primes[pcnt++] = i;
        }
        free(is_prime);

        ll bestP = 0, bestQ = 0, bestArea = 0;

        for (int i = 0; i < pcnt; ++i) {
            ll p = primes[i];
            for (int j = i; j < pcnt; ++j) {
                ll q = primes[j];
                ll area = p * q;
                if (area > m) break;

                /* Need a/b <= p/q <= 1, with p <= q due to j >= i */
                if (p * b >= q * a) {
                    if (area > bestArea) {
                        bestArea = area;
                        bestP = p;
                        bestQ = q;
                    }
                }
            }
        }

        free(primes);
        printf("%lld %lld\n", bestP, bestQ);
    }

    return 0;
}
